def title_case(s: str) -> str:
    result = []
    is_new_word = True
    for char in s:
        if char.isspace():
            result.append(char)
            is_new_word = True
        else:
            if is_new_word:
                result.append(char.upper())
                is_new_word = False
            else:
                result.append(char.lower())
    return "".join(result)
```

